function makeIssue([slug, category, title, query, symptom, answer, inputs, verification, correction, stopCondition]) {
  const links = categoryLinks[category];
  return {
    slug,
    category,
    title,
    query,
    symptom,
    answer,
    publishedDate,
    causes: [
      ["Released input does not match reality", `The active drawing, material definition, hardware rule, or quantity may not reflect ${inputs}.`],
      ["The physical condition was not verified", `The plan can appear valid until the shop or site attempts to ${verification}.`],
      ["A downstream fix hides the source", `The project may be changed before its source is understood. The documented correction is to ${correction}; use it only after the checks identify the cause.`],
    ],
    checks: [
      ["Source record", `Find the current revision and verify ${inputs}.`, "A missing or conflicting field points to a source-control problem.", "Correct and reissue the source before changing physical work."],
      ["Physical test", `Preserve the current condition, then ${verification}.`, "A repeatable mismatch identifies the real geometric, material, or process constraint.", "Record the measurement and compare it with the released acceptance rule."],
      ["Single-variable test", "Duplicate the plan or use a representative coupon and change only the most likely controlling input.", "If the symptom changes, that variable is causally relevant rather than merely correlated.", `Use that evidence to ${correction}.`],
      ["First-article gate", "Make or dry-fit one controlled part after the correction and compare it with every dependent dimension, face, and operation.", "A passing first article shows the correction works in the real process.", "Release the remaining batch only after the result is labeled and approved."],
    ],
    fixSteps: [
      "Quarantine the affected document, material, setup, or parts without destroying the evidence.",
      `Verify the controlling inputs: ${inputs}.`,
      `Create a repeatable check: ${verification}.`,
      `Apply the smallest supported correction: ${correction}.`,
      "Approve one first article, update the project revision, and release downstream work from that same source.",
    ],
    prevention: [
      `Store ${inputs} in the released project record.`,
      "Use stable part IDs, material codes, faces, datums, and revision labels.",
      "Verify one physical sample before repeating a new or changed operation.",
      "Keep calculators, layouts, labels, purchase totals, and shop documents on the same revision.",
      "Record the actual result and feed it back into the next estimate or template.",
    ],
    stopCondition,
    links,
  };
}

export const troubleshootingBatch20260720 = topics.map(makeIssue);

